import io, struct
import pandas as pd
from pathlib import Path

def load(name):
    p = Path('pandas/tests/io/sas/data')/name
    return bytearray(p.read_bytes())

def patch_and_run(name, off, nbytes):
    b = load(name)
    if nbytes == 4:
        b[off:off+4] = (0x7FFFFFF0).to_bytes(4, 'little', signed=False)
    else:
        b[off:off+8] = (0x7FFFFFF0).to_bytes(8, 'little', signed=False)
    try:
        pd.read_sas(io.BytesIO(bytes(b)), format='sas7bdat', encoding=None)
    except Exception as e:
        return type(e).__name__, str(e)
    return 'NO_EXCEPTION', ''

cases = [
    ('test1.sas7bdat', 130612, 4, 816),
    ('test2.sas7bdat', 130612, 4, 809),
    ('test7.sas7bdat', 130304, 8, 816),
]

results = {}
for fname, off, nbytes, known in cases:
    b = load(fname)
    # sanity: known-good row_length (before patch)
    if nbytes == 4:
        before = int.from_bytes(b[off:off+4], 'little', signed=False)
    else:
        before = int.from_bytes(b[off:off+8], 'little', signed=False)
    assert before == known, (fname, off, before, known)

    rtype, msg = patch_and_run(fname, off, nbytes)
    results[fname] = (rtype, msg)

for k,(t,m) in results.items():
    print(k, '=>', t)
    print(m)
    assert t == 'ValueError'
    ml = m.lower()
    assert 'row_length' in ml
    assert 'page size' in ml or 'pagesize' in ml
PY

